'use client';
import { useFinanceData } from '@/lib/api';
import { useEffect, useState } from 'react';
import { motion } from 'framer-motion';

const NetWorthCard = () => {
  const { data, isLoading, error } = useFinanceData('/api/finance/overview/net-worth');
  const [values, setValues] = useState<number[]>([]);

  useEffect(() => {
    if (data) {
      setValues(data.trend.map(p => p.net_worth));
    }
  }, [data]);

  if (isLoading) return <div>Loading...</div>;
  if (error) return <div>Error: {error.message}</div>;

  const hasData = values.length > 0;
  const max = hasData ? Math.max(...values) : 1;
  const min = hasData ? Math.min(...values) : 0;
  const range = (max - min) || 1;

  const sparkline = (
    <svg width="100%" height="50" viewBox="0 0 100 50" xmlns="http://www.w3.org/2000/svg">
      <polyline
        points={values.map((value, index) => {
          const x = index / (values.length - 1) * 100;
          const y = 35 - ((value - min) / range) * 30;
          return `${x},${y}`;
        }).join(' ')}
        fill="none"
        stroke="var(--primary)"
        strokeWidth="2"
      />
    </svg>
  );

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.5 }}
      className="bg-white p-4 rounded-lg shadow-md"
    >
      <h2 className="text-lg font-semibold">Net Worth</h2>
      {hasData ? sparkline : <div>No data available</div>}
    </motion.div>
  );
};

export default NetWorthCard;
